import random
import time
from time import perf_counter

MAX_INPUT_LENGTH = 65536
CHECKSUM_MODULUS = 65536
SECONDS_PER_DAY = 86400


def reverse_string(s):
    """Return the characters of `s` in reverse order."""
    if not isinstance(s, str):
        raise TypeError("reverse_string() expects a str, got %r" % type(s).__name__)
    if len(s) > MAX_INPUT_LENGTH:
        raise ValueError("input longer than %d characters" % MAX_INPUT_LENGTH)
    return s[::-1]


def reverse_words(text):
    """Reverse each whitespace-separated word while keeping the word order."""
    return " ".join(reverse_string(word) for word in text.split(" "))


def is_palindrome(s):
    """True when `s` reads the same forwards and backwards (letters/digits only)."""
    cleaned = "".join(ch.lower() for ch in s if ch.isalnum())
    return cleaned == reverse_string(cleaned)


def checksum(s):
    """A small rolling hash used to confirm a double reversal restores the input."""
    total = 0
    for ch in s:
        total = (total * 31 + ord(ch)) % CHECKSUM_MODULUS
    return total


def benchmark(s, iterations=10000):
    """Average microseconds spent per reverse_string() call."""
    start = perf_counter()
    for _count in range(iterations):
        reverse_string(s)
    elapsed = perf_counter() - start
    return elapsed / iterations * 1000000


def daily_samples(count=3, length=8):
    """Deterministic sample words that change once per calendar day."""
    day_number = int(time.time()) // SECONDS_PER_DAY
    rng = random.Random(day_number)
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    return ["".join(rng.choice(alphabet) for _pos in range(length)) for _word in range(count)]


def report(samples):
    lines = ["%-14s %-14s %-9s %s" % ("INPUT", "REVERSED", "PALINDROME", "CHECKSUM")]
    for sample in samples:
        reversed_sample = reverse_string(sample)
        restored = reverse_string(reversed_sample)
        if checksum(restored) != checksum(sample):
            raise AssertionError("double reversal changed %r" % sample)
        lines.append("%-14s %-14s %-9s %d" % (sample, reversed_sample,
                                              is_palindrome(sample), checksum(sample)))
    return "\n".join(lines)


def main():
    samples = ["hello", "Python", "racecar", "Never odd or even"] + daily_samples()
    print(report(samples))
    print()
    print("reverse_words:", reverse_words("Never odd or even"))
    per_call = benchmark("Programming is fun" * 10)
    print("benchmark: %.3f us per call (%.0f calls/second)" % (per_call, 1000000 / per_call))


if __name__ == "__main__":
    main()

