VOWELS = frozenset("aeiou")


def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u) in `text`, ignoring case."""
    if not isinstance(text, str):
        raise TypeError("text must be a string, got %s" % type(text).__name__)
    total = 0
    for char in text.lower():
        if char in VOWELS:
            total += 1
    return total


def vowels_per_10k(text):
    """Vowel density expressed as vowels per 10000 characters."""
    if not text:
        return 0.0
    return count_vowels(text) * 10000 / len(text)


def count_vowels_in_stream(stream, chunk_size=65536):
    """Count vowels in a file-like object without loading it entirely."""
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")
    total = 0
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            return total
        total += count_vowels(chunk)


def format_count(count):
    """Render a vowel count compactly, switching to millions when large."""
    if count >= 1000000:
        return "%.2fM" % (count / 1000000)
    return "{:,}".format(count)


def projected_daily_vowels(count, elapsed_seconds):
    """Extrapolate a measured count over a full day of 86400 seconds."""
    if elapsed_seconds <= 0:
        raise ValueError("elapsed_seconds must be positive")
    return int(round(count / elapsed_seconds * 86400))


def report(samples):
    lines = []
    for text in samples:
        label = text if len(text) <= 20 else text[:17] + "..."
        lines.append(
            "%-22s vowels=%-4d density=%7.1f per 10k"
            % (repr(label), count_vowels(text), vowels_per_10k(text))
        )
    return "\n".join(lines)


def main():
    import io
    import time

    samples = ["Hello World", "Python", "", "AEIOU aeiou", "rhythm myths"]
    print(report(samples))

    document = io.StringIO("Hello World " * 10000)
    started = time.perf_counter()
    streamed = count_vowels_in_stream(document)
    elapsed = time.perf_counter() - started

    print("streamed vowels: %s" % format_count(streamed))
    print("projected in one day: %s" % format_count(
        projected_daily_vowels(streamed, elapsed)))


if __name__ == "__main__":
    main()

