import re
from collections import Counter

MAX_TEXT_LENGTH = 1000000
MAX_HASHTAGS = 10000
CACHE_LIMIT = 65536
SECONDS_PER_DAY = 86400

_HASHTAG_RE = re.compile(r'#(\w+)')
_CACHE = {}


def extract_hashtags(text):
    """Return the hashtags found in `text`, stripped of the leading '#'."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if len(text) > MAX_TEXT_LENGTH:
        raise ValueError("text must not exceed %d characters" % MAX_TEXT_LENGTH)
    cached = _CACHE.get(text)
    if cached is not None:
        return list(cached)
    tags = _HASHTAG_RE.findall(text)
    if len(tags) > MAX_HASHTAGS:
        tags = tags[:MAX_HASHTAGS]
    if len(_CACHE) >= CACHE_LIMIT:
        _CACHE.clear()
    _CACHE[text] = tags
    return list(tags)


def count_hashtags(texts):
    """Count hashtag occurrences (case-insensitively) across many texts."""
    counter = Counter()
    for text in texts:
        counter.update(tag.lower() for tag in extract_hashtags(text))
    return counter


def top_hashtags(counter, limit=5):
    ordered = sorted(counter.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


