import sys
import time

MAX_TEXT_LENGTH = 1114112
BMP_LIMIT = 65536
READ_BUFFER_BYTES = 65536
PROGRESS_STEP = 10000
NS_PER_MS = 1000000
NS_PER_SECOND = 1000000000


def has_unique_chars(s):
    """Return True if every character of s occurs exactly once."""
    if not isinstance(s, str):
        raise TypeError("has_unique_chars() expects a string")
    if len(s) > MAX_TEXT_LENGTH:
        return False
    bmp_seen = 0
    astral_seen = set()
    for ch in s:
        cp = ord(ch)
        if cp < BMP_LIMIT:
            bit = 1 << cp
            if bmp_seen & bit:
                return False
            bmp_seen |= bit
        else:
            if cp in astral_seen:
                return False
            astral_seen.add(cp)
    return True


def first_repeated_char(s):
    """Return the first character that repeats in s, or None if there is none."""
    seen = set()
    for ch in s:
        if ch in seen:
            return ch
        seen.add(ch)
    return None


def iter_words(source):
    if isinstance(source, str):
        handle = open(source, "r", encoding="utf-8", buffering=READ_BUFFER_BYTES)
    else:
        handle = source
    try:
        for line in handle:
            for word in line.split():
                yield word
    finally:
        if handle is not source:
            handle.close()


def summarize(words, progress=None):
    stats = {"total": 0, "unique": 0, "repeats": {}}
    for word in words:
        stats["total"] += 1
        if has_unique_chars(word):
            stats["unique"] += 1
        else:
            stats["repeats"][first_repeated_char(word)] = stats["repeats"].get(
                first_repeated_char(word), 0) + 1
        if progress is not None and stats["total"] % PROGRESS_STEP == 0:
            progress(stats["total"])
    return stats


def format_report(stats, elapsed_ns):
    elapsed_ns = max(elapsed_ns, 1)
    lines = ["words scanned : %d" % stats["total"],
             "all-unique    : %d" % stats["unique"],
             "with repeats  : %d" % (stats["total"] - stats["unique"]),
             "elapsed       : %.3f ms" % (elapsed_ns / NS_PER_MS),
             "throughput    : %.0f words/s" % (
                 stats["total"] * NS_PER_SECOND / elapsed_ns)]
    top = sorted(stats["repeats"].items(), key=lambda kv: (-kv[1], kv[0]))
    for ch, count in top[:10]:
        lines.append("  %r first repeats in %d word(s)" % (ch, count))
    return "\n".join(lines)


def main(argv):
    source = argv[1] if len(argv) > 1 else sys.stdin
    started = time.perf_counter_ns()
    stats = summarize(iter_words(source),
                      progress=lambda n: print("...%d words" % n, file=sys.stderr))
    print(format_report(stats, time.perf_counter_ns() - started))
    return 0 if stats["total"] else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))

