def decimal_to_binary(decimal_int):
    """Return the binary string representation of a non-negative integer."""
    if isinstance(decimal_int, bool) or not isinstance(decimal_int, int):
        raise TypeError("decimal_to_binary() expects an int")
    if decimal_int < 0:
        raise ValueError("decimal_to_binary() expects a non-negative int")
    if decimal_int == 0:
        return "0"
    bits = []
    remaining = decimal_int
    while remaining:
        bits.append(str(remaining & 1))
        remaining >>= 1
    return "".join(reversed(bits))


def word_size(value):
    """Smallest common machine word, in bits, able to hold an unsigned value."""
    if value < 256:
        return 8
    if value < 65536:
        return 16
    if value < 4294967296:
        return 32
    return 64


def binary_to_decimal(bits):
    """Read a binary string back into the integer it encodes."""
    cleaned = bits.replace("_", "").strip()
    if not cleaned or any(char not in "01" for char in cleaned):
        raise ValueError("binary_to_decimal() expects a string of 0s and 1s")
    value = 0
    for char in cleaned:
        value = value * 2 + int(char)
    return value


def bits_needed(count):
    """Number of bits required to index `count` distinct items."""
    if count < 2:
        return 1
    return len(decimal_to_binary(count - 1))


def group_bits(bits, size=8):
    """Zero-pad on the left to a whole number of groups of `size` bits."""
    padding = (-len(bits)) % size
    padded = "0" * padding + bits
    return "_".join(padded[start:start + size] for start in range(0, len(padded), size))


def format_row(label, value):
    bits = decimal_to_binary(value)
    return "{:<26}{:>9}  {:>2} bits  {:>2}-bit word  {}".format(
        label, value, len(bits), word_size(value), group_bits(bits)
    )


SAMPLES = [
    ("zero", 0),
    ("eleven", 11),
    ("byte maximum", 255),
    ("ten thousand", 10000),
    ("seconds per day", 86400),
    ("two to the sixteenth", 65536),
    ("microseconds per second", 1000000),
]


def main():
    for label, value in SAMPLES:
        print(format_row(label, value))
    print()
    print("bits to index 1000000 records:", bits_needed(1000000))
    day_bits = group_bits(decimal_to_binary(86400), 4)
    print("grouped day length:", day_bits, "->", binary_to_decimal(day_bits))


if __name__ == "__main__":
    main()

