import random
import time
from functools import reduce

MAX_SUPPORTED_N = 1000000
XOR_CHUNK = 65536
SMALL_BENCH_N = 10000
LARGE_BENCH_N = 200000
NANOS_PER_SECOND = 1000000000


def validate_sequence(numbers):
    """Check that numbers is 1..N with exactly one value missing."""
    n = len(numbers) + 1
    if n > MAX_SUPPORTED_N:
        raise ValueError("sequences longer than %d entries are not supported" % MAX_SUPPORTED_N)
    seen = bytearray(n + 1)
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("expected integers, got %r" % (value,))
        if value < 1 or value > n:
            raise ValueError("value %d outside the range 1..%d" % (value, n))
        if seen[value]:
            raise ValueError("duplicate value %d" % value)
        seen[value] = 1
    return n


def find_missing_number(numbers):
    """Return the single missing value of the unsorted range 1..N."""
    n = validate_sequence(numbers)
    return n * (n + 1) // 2 - sum(numbers)


def find_missing_number_xor(numbers):
    """Same result via chunked XOR, which never builds a huge intermediate sum."""
    n = len(numbers) + 1
    acc = 0
    for start in range(1, n + 1, XOR_CHUNK):
        acc ^= reduce(lambda a, b: a ^ b, range(start, min(start + XOR_CHUNK, n + 1)))
    for start in range(0, len(numbers), XOR_CHUNK):
        acc ^= reduce(lambda a, b: a ^ b, numbers[start:start + XOR_CHUNK])
    return acc


def make_sequence(n, missing, seed=917):
    """Build a shuffled copy of 1..N with `missing` removed."""
    if missing < 1 or missing > n:
        raise ValueError("missing value must lie in 1..%d" % n)
    values = [v for v in range(1, n + 1) if v != missing]
    random.Random(seed).shuffle(values)
    return values


def report(n, missing, found, elapsed_ns):
    status = "ok" if found == missing else "MISMATCH (got %d)" % found
    micros = elapsed_ns / 1000.0
    rate = n * NANOS_PER_SECOND / max(elapsed_ns, 1)
    return "N=%-8d missing=%-8d %-20s %.1f us  %.0f values/s" % (n, missing, status, micros, rate)


def main():
    for sample, expected in (([1, 2, 4, 5], 3), ([5, 1, 3, 2], 4), ([2], 1)):
        found = find_missing_number(sample)
        print("%-14s -> %d (expected %d)" % (sample, found, expected))

    for n in (SMALL_BENCH_N, LARGE_BENCH_N):
        missing = n // 3 + 1
        values = make_sequence(n, missing)
        start = time.perf_counter_ns()
        found = find_missing_number(values)
        elapsed_ns = time.perf_counter_ns() - start
        print(report(n, missing, found, elapsed_ns))
        crosscheck = find_missing_number_xor(values)
        if crosscheck != found:
            raise AssertionError("xor method disagrees: %d vs %d" % (crosscheck, found))


if __name__ == "__main__":
    main()

