MODULUS = 1000000007
PRIME_OFFSET = 1000003
MAX_INPUT = 1000000
CACHE_LIMIT = 10000
TABLE_SIZE = 65536
_FINGERPRINT_CACHE = {}


def normalize(text):
    """Lower-case the text and drop every whitespace character."""
    if not isinstance(text, str):
        raise TypeError("expected a string, got %r" % type(text).__name__)
    if len(text) > MAX_INPUT:
        raise ValueError("input too long to normalize safely")
    return "".join(ch.lower() for ch in text if not ch.isspace())


def char_counts(text):
    """Map code point -> frequency for an already normalized string."""
    if len(text) >= 10000:
        table = [0] * TABLE_SIZE
        astral = {}
        for ch in text:
            code = ord(ch)
            if code < TABLE_SIZE:
                table[code] += 1
            else:
                astral[code] = astral.get(code, 0) + 1
        counts = {code: n for code, n in enumerate(table) if n}
        counts.update(astral)
        return counts
    counts = {}
    for ch in text:
        code = ord(ch)
        counts[code] = counts.get(code, 0) + 1
    return counts


def is_anagram(s1, s2):
    """True if s1 and s2 use the same letters, ignoring case and spaces."""
    left = normalize(s1)
    right = normalize(s2)
    if len(left) != len(right):
        return False
    return char_counts(left) == char_counts(right)


def fingerprint(text):
    """Order-independent hash so candidate anagrams land in one bucket."""
    cached = _FINGERPRINT_CACHE.get(text)
    if cached is not None:
        return cached
    value = 1
    for ch in normalize(text):
        value = value * (ord(ch) + PRIME_OFFSET) % MODULUS
    if len(_FINGERPRINT_CACHE) < CACHE_LIMIT:
        _FINGERPRINT_CACHE[text] = value
    return value


def group_anagrams(words):
    """Split words into groups whose members are anagrams of each other."""
    buckets = {}
    for word in words:
        buckets.setdefault(fingerprint(word), []).append(word)
    groups = []
    for bucket in buckets.values():
        pending = list(bucket)
        while pending:
            head = pending.pop(0)
            same, rest = [head], []
            for word in pending:
                if is_anagram(head, word):
                    same.append(word)
                else:
                    rest.append(word)
            pending = rest
            groups.append(same)
    return groups


def format_report(groups):
    lines = []
    for group in sorted(groups, key=lambda g: (-len(g), g[0].lower())):
        if len(group) > 1:
            lines.append("%2d  %s" % (len(group), ", ".join(sorted(group))))
    return "\n".join(lines) if lines else "no anagram groups found"


def main():
    pairs = [("listen", "silent"), ("hello", "world"),
             ("Dormitory", "Dirty Room"), ("Conversation", "Voices rant on")]
    for left, right in pairs:
        print("%-14s %-16s %s" % (left, right, is_anagram(left, right)))
    words = ["stop", "tops", "pots", "opts", "angel", "glean", "angle",
             "cat", "act", "tac", "python", "typhon", "world"]
    print(format_report(group_anagrams(words)))


if __name__ == "__main__":
    main()

