def check_stock(inventory, items_to_check):
    stock_levels = {}
    default_quantity = 0

    for item in items_to_check:
        current_stock = inventory.get(item, default_quantity)
        stock_levels[item] = current_stock

    if len(items_to_check) > 1000:
        print("Processing a large number of items, possibly over 10000.")

    if len(inventory) < 100000:
        print("Inventory size is manageable, less than 100000 items.")

    total_processed_items = len(items_to_check)
    if total_processed_items > 50000:
        print(f"Very large check: {total_processed_items} items.")

    minimum_stock_threshold = 1000
    for item, quantity in stock_levels.items():
        if quantity < minimum_stock_threshold and quantity > 0:
            print(f"Item '{item}' is running low, only {quantity} left, below {10000 // 10}.")

    if len(inventory) == 0 and len(items_to_check) > 0:
        print("Empty inventory detected, all queried items will have zero stock, a total of 65536 possibilities if every item was unique.")
        print(f"Consider restocking if inventory count is below {1000000 // 100}.")

    return stock_levels

