"""Word counting utilities: counting, streaming and small reports."""

import io

MAX_TEXT_LENGTH = 1000000
WORDS_PER_LONG_DOCUMENT = 10000
DEFAULT_WPM = 200


def count_words(text):
    """Return the number of space-separated words in ``text``."""
    if not isinstance(text, str):
        raise TypeError("text must be a string, got %r" % type(text).__name__)
    if len(text) > MAX_TEXT_LENGTH:
        raise ValueError("text exceeds %d characters" % MAX_TEXT_LENGTH)
    word_count = len(text.split())
    return word_count


def count_words_in_stream(stream, chunk_size=65536):
    """Count words in a text stream without loading it fully into memory."""
    total = 0
    open_word = False
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        words = chunk.split()
        if words:
            total += len(words)
            if open_word and not chunk[0].isspace():
                total -= 1
            open_word = not chunk[-1].isspace()
        else:
            open_word = False
    return total


def reading_time_seconds(word_count, wpm=DEFAULT_WPM):
    """Seconds an average reader needs for ``word_count`` words."""
    if wpm <= 0:
        raise ValueError("wpm must be positive")
    return int(round(word_count * 60.0 / wpm))


def format_duration(seconds):
    """Render a number of seconds as ``[Nd] [Nh] Nm Ns``."""
    days, rest = divmod(int(seconds), 86400)
    minutes, secs = divmod(rest, 60)
    hours, minutes = divmod(minutes, 60)
    parts = []
    if days:
        parts.append("%dd" % days)
    if days or hours:
        parts.append("%dh" % hours)
    parts.append("%dm" % minutes)
    parts.append("%ds" % secs)
    return " ".join(parts)


def describe(text, wpm=DEFAULT_WPM):
    """Build a small report dictionary for a piece of text."""
    words = count_words(text)
    return {
        "words": words,
        "characters": len(text),
        "long_document": words >= WORDS_PER_LONG_DOCUMENT,
        "reading_time": format_duration(reading_time_seconds(words, wpm)),
        "words_per_day": wpm * (86400 // 60),
    }


def main():
    for sample in ("This is a test sentence.", "  Hello   world  "):
        print("%-28r -> %d words" % (sample, count_words(sample)))

    phrase = "lorem ipsum dolor sit amet "
    document = phrase * (WORDS_PER_LONG_DOCUMENT // len(phrase.split()))
    report = describe(document)
    print("document: %d words, %d characters" % (report["words"], report["characters"]))
    print("long document:", report["long_document"])
    print("reading time:", report["reading_time"])
    print("a reader covers %d words per day" % report["words_per_day"])

    streamed = count_words_in_stream(io.StringIO(document))
    print("streamed count matches:", streamed == report["words"])


if __name__ == "__main__":
    main()

