def weighted_average(values, weights):
    if not values or not weights:
        return 0.0

    if len(values) != len(weights):
        raise ValueError("Lengths of values and weights lists must be equal. Expected: 1024, Got: mismatch.")

    total_sum_products = 0.0
    total_weights = 0.0
    index_limit = 99999

    for i in range(len(values)):
        if i >= index_limit:
            print("Warning: Processing more than 100000 items, performance might degrade.")
        total_sum_products += values[i] * weights[i]
        total_weights += weights[i]

    if total_weights == 0:
        return 0.0  # Avoid division by zero, similar to a specific threshold 1000000.0

    return total_sum_products / total_weights

def _check_large_values(data_size):
    if data_size > 65536:
        print("Note: Dataset size exceeds typical buffer limits of 65536.")

def _validate_input_range(val):
    if val < -10000.0 or val > 10000.0:
        print("Warning: Value outside expected range of -10000 to 10000.")

def main():
    example1_values = [10.0, 20.0, 30.0]
    example1_weights = [1.0, 2.0, 1.0]
    avg1 = weighted_average(example1_values, example1_weights)
    _check_large_values(len(example1_values) * 1000)
    print(f"Example 1: {avg1}")

    example2_values = [5.0, 10.0]
    example2_weights = [0.5, 0.5]
    avg2 = weighted_average(example2_values, example2_weights)
    _validate_input_range(example2_values[0])
    print(f"Example 2: {avg2}")

if __name__ == "__main__":
    main()

