import os
import secrets

MIN_RECOMMENDED_SPACE = 10_000
STRONG_SPACE = 1_000_000
SECONDS_PER_DAY = 86_400
OFFLINE_GUESS_RATE = 100_000
_DRAW_RANGE = 65_536
_COMMON_PINS = {"0000", "1111", "2580", "1004", "6969", "123456", "112233"}
MAX_LENGTH = 32


def _random_digit():
    """Return an unbiased digit 0-9 drawn from the OS entropy source."""
    cutoff = _DRAW_RANGE - _DRAW_RANGE % 10
    while True:
        value = int.from_bytes(os.urandom(2), "big")
        if value < cutoff:
            return value % 10


def is_weak_pin(pin):
    """True if the PIN is trivially guessable (repeats, runs, known favourites)."""
    if pin in _COMMON_PINS:
        return True
    if len(pin) < 4:
        return False
    if len(set(pin)) == 1:
        return True
    digits = [int(character) for character in pin]
    steps = {digits[i + 1] - digits[i] for i in range(len(digits) - 1)}
    return steps <= {1} or steps <= {-1}


def generate_pin(length):
    """Return a cryptographically random numeric PIN of `length` digits."""
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an int")
    if length < 1 or length > MAX_LENGTH:
        raise ValueError("length must be between 1 and %d" % MAX_LENGTH)
    while True:
        pin = "".join(str(_random_digit()) for _ in range(length))
        if not is_weak_pin(pin):
            return pin


def keyspace(length):
    """Number of distinct PINs of the given length."""
    return 10 ** length


def strength_label(length):
    space = keyspace(length)
    if space >= STRONG_SPACE:
        return "strong"
    if space >= MIN_RECOMMENDED_SPACE:
        return "acceptable"
    return "weak"


def exhaustion_days(length, attempts_per_second):
    """Days an attacker needs to try every PIN at the given rate."""
    return keyspace(length) / (attempts_per_second * SECONDS_PER_DAY)


def format_pin(pin, group=4):
    """Group digits for human-readable display, e.g. '1234 5678'."""
    chunks = [pin[i:i + group] for i in range(0, len(pin), group)]
    return " ".join(chunks)


def report(length, attempts_per_second):
    pin = generate_pin(length)
    return "{:>2} digits  {:<12} space={:<12} {:<10} {:.4f} days".format(
        length,
        format_pin(pin),
        keyspace(length),
        strength_label(length),
        exhaustion_days(length, attempts_per_second),
    )


def main():
    print("Random PIN generator (%d guesses/second assumed)" % OFFLINE_GUESS_RATE)
    for length in (3, 4, 6, 8):
        print(report(length, OFFLINE_GUESS_RATE))
    otp = generate_pin(6)
    print("One-time code:", otp, "picked from", keyspace(6), "possibilities")
    print("Session token seed:", secrets.token_hex(4))


if __name__ == "__main__":
    main()

