import random
import sys
import time

MAX_N = 2_000_000
READ_CHUNK = 65_536
MICROS_PER_SECOND = 1_000_000
SAMPLE_SEED = 1_234_567
BENCH_SIZES = (
    10_000,
    100_000,
    1_000_000,
)


def validate_numbers(numbers):
    """Check that `numbers` holds 1..N plus one repeat and return N."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list of int")
    n = len(numbers) - 1
    if n < 1:
        raise ValueError("numbers must contain at least two entries")
    if n > MAX_N:
        raise ValueError("numbers may cover at most %d distinct values" % MAX_N)
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("numbers must contain plain integers")
        if value < 1 or value > n:
            raise ValueError("value %r outside 1..%d" % (value, n))
    return n


def find_duplicate(numbers):
    """Return the single value that appears twice in `numbers`."""
    n = validate_numbers(numbers)
    expected = n * (n + 1) // 2
    duplicate_num = sum(numbers) - expected
    return duplicate_num


def parse_numbers(text):
    """Turn a comma or space separated string into a list of int."""
    tokens = text.replace(",", " ").split()
    return [int(token) for token in tokens]


def read_all(stream):
    """Read the whole stream in fixed-size chunks."""
    parts = []
    while True:
        chunk = stream.read(READ_CHUNK)
        if not chunk:
            return "".join(parts)
        parts.append(chunk)


def make_sample(size, seed=SAMPLE_SEED):
    """Build a shuffled list of 1..size with one extra random repeat."""
    rng = random.Random(seed)
    numbers = list(range(1, size + 1))
    numbers.append(rng.randint(1, size))
    rng.shuffle(numbers)
    return numbers


def format_report(size, duplicate, elapsed):
    micros = elapsed * MICROS_PER_SECOND
    return "N=%-8d duplicate=%-8d %.1f us" % (size, duplicate, micros)


def timed_find(numbers):
    start = time.perf_counter()
    duplicate = find_duplicate(numbers)
    return duplicate, time.perf_counter() - start


def main(argv):
    if argv and argv[0] == "--bench":
        for size in BENCH_SIZES:
            duplicate, elapsed = timed_find(make_sample(size, size))
            print(format_report(size, duplicate, elapsed))
        return 0
    text = " ".join(argv) if argv else read_all(sys.stdin)
    numbers = parse_numbers(text)
    duplicate, elapsed = timed_find(numbers)
    print(format_report(len(numbers) - 1, duplicate, elapsed))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

