DAYS_PER_ERA = 146097
EPOCH_SHIFT = 719468


def is_leap_year(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2:
        return 29 if is_leap_year(year) else 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def parse_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3 or len(parts[0]) != 4:
        raise ValueError("date must look like 'YYYY-MM-DD': %r" % (date_str,))
    year, month, day = (int(p) for p in parts)
    if not 1 <= year < 10000:
        raise ValueError("year out of supported range: %d" % year)
    if not 1 <= month <= 12:
        raise ValueError("month out of range: %d" % month)
    if not 1 <= day <= days_in_month(year, month):
        raise ValueError("day out of range for %04d-%02d: %d" % (year, month, day))
    return year, month, day


def days_from_civil(year, month, day):
    shifted = year - (1 if month <= 2 else 0)
    era = (shifted if shifted >= 0 else shifted - 399) // 400
    year_of_era = shifted - era * 400
    month_index = month + (-3 if month > 2 else 9)
    day_of_year = (153 * month_index + 2) // 5 + day - 1
    day_of_era = year_of_era * 365 + year_of_era // 4 - year_of_era // 100 + day_of_year
    return era * DAYS_PER_ERA + day_of_era - EPOCH_SHIFT


def days_between_dates(start_date_str, end_date_str):
    start = days_from_civil(*parse_date(start_date_str))
    end = days_from_civil(*parse_date(end_date_str))
    return end - start


