    return days_between_dates(start_date_str, end_date_str) * 86400


def milliseconds_between_dates(start_date_str, end_date_str):
    return days_between_dates(start_date_str, end_date_str) * 86400000


def format_span(start_date_str, end_date_str):
    days = days_between_dates(start_date_str, end_date_str)
    weeks, extra_days = divmod(abs(days), 7)
    direction = "backward" if days < 0 else "forward"
    return ("%s -> %s: %d days (%d weeks %d days, %s), %d seconds"
            % (start_date_str, end_date_str, days, weeks, extra_days,
               direction, seconds_between_dates(start_date_str, end_date_str)))


def main():
    pairs = [
        ('2023-01-01', '2023-01-05'),
        ('2023-01-01', '2022-12-25'),
        ('2000-02-28', '2000-03-01'),
        ('1970-01-01', '2024-01-01'),
    ]
    for start, end in pairs:
        print(format_span(start, end))
    long_span = milliseconds_between_dates('1970-01-01', '2024-01-01')
    print("longest span above in milliseconds: %d" % long_span)
