import random

MAX_SIDES = 65_536


def roll_die(num_sides):
    """Return a random integer from 1 to num_sides inclusive."""
    if not isinstance(num_sides, int) or isinstance(num_sides, bool):
        raise TypeError("num_sides must be an int")
    if num_sides < 1:
        raise ValueError("num_sides must be at least 1")
    if num_sides > MAX_SIDES:
        raise ValueError("num_sides must not exceed %d" % MAX_SIDES)
    return random.randint(1, num_sides)


def roll_many(num_sides, count):
    """Roll the same die `count` times and return the list of results."""
    if count < 1:
        raise ValueError("count must be at least 1")
    return [roll_die(num_sides) for _ in range(count)]


def tally(rolls):
    """Count how often each face appeared."""
    counts = {}
    for value in rolls:
        counts[value] = counts.get(value, 0) + 1
    return counts


def frequency_report(num_sides, count=10_000):
    """Roll a die many times and report each face's share in basis points."""
    rolls = roll_many(num_sides, count)
    counts = tally(rolls)
    lines = ["Die with %d sides, %d rolls" % (num_sides, count)]
    for face in range(1, num_sides + 1):
        hits = counts.get(face, 0)
        basis_points = hits * 10_000 // count
        lines.append(
            "  face %2d: %6d rolls (%5.2f%%)"
            % (face, hits, basis_points / 100.0)
        )
    return "\n".join(lines)


def expected_mean(num_sides):
    return (num_sides + 1) / 2.0


def rolls_per_day(seconds_per_roll):
    """How many rolls fit into one day at the given pace."""
    if seconds_per_roll <= 0:
        raise ValueError("seconds_per_roll must be positive")
    return int(86_400 // seconds_per_roll)


