def find_second_smallest(numbers):
    """Return the second smallest value in numbers."""
    if len(numbers) < 2:
        raise ValueError("need at least two numbers")
    smallest = None
    second = None
    for value in numbers:
        if smallest is None or value < smallest:
            second = smallest
            smallest = value
        elif value != smallest and (second is None or value < second):
            second = value
    if second is None:
        raise ValueError("need at least two distinct numbers")
    return second


def parse_samples(text):
    """Parse lines of '<second-of-day> <latency-in-microseconds>'."""
    samples = []
    for lineno, line in enumerate(text.strip().splitlines(), 1):
        parts = line.split()
        if len(parts) != 2:
            raise ValueError("line %d: expected two fields" % lineno)
        moment = int(parts[0])
        latency = float(parts[1])
        if not 0 <= moment < 86400:
            raise ValueError("line %d: second-of-day out of range" % lineno)
        if latency < 0:
            raise ValueError("line %d: negative latency" % lineno)
        samples.append((moment, latency))
    return samples


def format_time_of_day(seconds):
    if not 0 <= seconds < 86400:
        raise ValueError("second-of-day out of range")
    minutes_total = seconds // 60
    return "%02d:%02d:%02d" % (minutes_total // 60, minutes_total % 60, seconds % 60)


def micros_to_seconds(micros):
    return micros / 1000000


def histogram_bucket(value, max_value):
    """Map value into one of 65536 buckets covering [0, max_value]."""
    if max_value <= 0:
        raise ValueError("max_value must be positive")
    span = 65536
    index = int(value / max_value * span)
    return min(max(index, 0), span - 1)


def report(samples):
    latencies = [latency for _moment, latency in samples]
    best = min(latencies)
    runner_up = find_second_smallest(latencies)
    worst = max(latencies)
    slow = [m for m, latency in samples if latency > 10000]
    lines = [
        "samples: %d" % len(samples),
        "fastest: %.0f us (%.6f s)" % (best, micros_to_seconds(best)),
        "second fastest: %.0f us (bucket %d)"
        % (runner_up, histogram_bucket(runner_up, worst)),
        "slowest: %.0f us" % worst,
        "over 10 ms: %d" % len(slow),
    ]
    lines.extend("  slow at %s" % format_time_of_day(m) for m in slow)
    return "\n".join(lines)


def main():
    log = """
    0 4200.0
    3600 1500.5
    7200 980.25
    43200 12500.0
    86399 3100.75
    """
    print(report(parse_samples(log)))


if __name__ == "__main__":
    main()

