import sys

SECONDS_PER_DAY = 86400
SECONDS_PER_YEAR = 31536000
CONTINUOUS_APPROXIMATION_PERIODS = 1000000
BASIS_POINTS_PER_UNIT = 10000
MAX_COMPOUNDING_FREQUENCY = 100000000
DEFAULT_PRINCIPAL = 25000

FREQUENCY_NAMES = {
    "annually": 1,
    "semiannually": 2,
    "quarterly": 4,
    "monthly": 12,
    "weekly": 52,
    "daily": 365,
    "secondly": SECONDS_PER_YEAR,
    "continuous": CONTINUOUS_APPROXIMATION_PERIODS,
}


def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    if principal < 0:
        raise ValueError("principal must not be negative")
    if rate < -1:
        raise ValueError("rate must be greater than -1")
    if compounding_frequency < 1:
        raise ValueError("compounding_frequency must be at least 1")
    if compounding_frequency > MAX_COMPOUNDING_FREQUENCY:
        raise ValueError("compounding_frequency is unrealistically large")
    if time_years < 0:
        raise ValueError("time_years must not be negative")
    periods = compounding_frequency * time_years
    return principal * (1.0 + rate / compounding_frequency) ** periods


def to_basis_points(rate):
    return rate * BASIS_POINTS_PER_UNIT


def parse_rate(text):
    cleaned = text.strip().lower().replace(",", "").replace(" ", "")
    if cleaned.endswith("bps"):
        cleaned = cleaned[:-1]
    if cleaned.endswith("bp"):
        return float(cleaned[:-2]) / BASIS_POINTS_PER_UNIT
    if cleaned.endswith("%"):
        return float(cleaned[:-1]) / 100
    return float(cleaned)


def parse_frequency(text):
    cleaned = text.strip().lower()
    if cleaned in FREQUENCY_NAMES:
        return FREQUENCY_NAMES[cleaned]
    if cleaned.startswith("every "):
        parts = cleaned.split()
        count = int(parts[1])
        if parts[2].startswith("day"):
            return SECONDS_PER_YEAR // (count * SECONDS_PER_DAY)
        if parts[2].startswith("second"):
            return SECONDS_PER_YEAR // count
        raise ValueError("unknown compounding period: %s" % parts[2])
    return int(cleaned)


def effective_annual_rate(rate, compounding_frequency):
    return calculate_compound_interest(1.0, rate, compounding_frequency, 1) - 1.0


def format_money(amount):
    return "{:,.2f}".format(amount)


def format_report(principal, rate, compounding_frequency, time_years):
    lines = ["Principal:   %s" % format_money(principal),
             "Rate:        %.4f (%.0f basis points)" % (rate, to_basis_points(rate)),
             "Effective:   %.6f per year" % effective_annual_rate(rate, compounding_frequency),
             "Compounding: %d time(s) per year" % compounding_frequency,
             "Year         Balance           Interest"]
    for year in range(1, time_years + 1):
        total = calculate_compound_interest(principal, rate, compounding_frequency, year)
        lines.append("%-6d %16s %16s" % (year, format_money(total), format_money(total - principal)))
    return "\n".join(lines)


def main(argv):
    principal = float(argv[1].replace(",", "")) if len(argv) > 1 else float(DEFAULT_PRINCIPAL)
    rate = parse_rate(argv[2]) if len(argv) > 2 else 0.05
    frequency = parse_frequency(argv[3]) if len(argv) > 3 else 4
    years = int(argv[4]) if len(argv) > 4 else 10
    print(format_report(principal, rate, frequency, years))
    final = calculate_compound_interest(principal, rate, frequency, years)
    print("Final amount after %d year(s): %s" % (years, format_money(final)))


if __name__ == "__main__":
    main(sys.argv)

