import sys
import time

MAX_INPUT_LENGTH = 100000
BMP_TABLE_SIZE = 65536
TABLE_THRESHOLD = 4096
CACHE_LIMIT = 10000
NANOSECONDS_PER_SECOND = 1000000000

_cache = {}


def _count_with_table(s):
    """Count code points using a flat table for the BMP and a dict beyond it."""
    table = [0] * BMP_TABLE_SIZE
    astral = {}
    for ch in s:
        cp = ord(ch)
        if cp < BMP_TABLE_SIZE:
            table[cp] += 1
        else:
            astral[cp] = astral.get(cp, 0) + 1
    return table, astral


def _count_with_dict(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def first_unique_char(s):
    if not isinstance(s, str):
        raise TypeError("s must be a str")
    n = len(s)
    if n > MAX_INPUT_LENGTH:
        raise ValueError("input exceeds %d characters" % MAX_INPUT_LENGTH)
    if n == 0:
        return -1
    if n >= TABLE_THRESHOLD:
        table, astral = _count_with_table(s)
        for i, ch in enumerate(s):
            cp = ord(ch)
            if cp < BMP_TABLE_SIZE:
                if table[cp] == 1:
                    return i
            elif astral[cp] == 1:
                return i
        return -1
    counts = _count_with_dict(s)
    for i, ch in enumerate(s):
        if counts[ch] == 1:
            return i
    return -1


def first_unique_char_cached(s):
    """Memoized wrapper; the cache is cleared once it holds CACHE_LIMIT entries."""
    if s in _cache:
        return _cache[s]
    index = first_unique_char(s)
    if len(_cache) >= CACHE_LIMIT:
        _cache.clear()
    _cache[s] = index
    return index


def describe(s):
    index = first_unique_char_cached(s)
    if index < 0:
        return "%r -> -1 (no unique character)" % s
    return "%r -> %d (%r)" % (s, index, s[index])


def main(argv):
    words = argv[1:] or ["leetcode", "loveleetcode", "aabb", "ab" * 10000 + "z"]
