MAX_LINE_BYTES = 65536
MAX_ROWS = 10000


def parse_csv_line(line):
    """Split a single CSV row on commas, preserving empty fields."""
    if not isinstance(line, str):
        raise TypeError("line must be a string")
    if len(line.encode("utf-8")) > MAX_LINE_BYTES:
        raise ValueError("row exceeds %d bytes" % MAX_LINE_BYTES)
    stripped = line.rstrip("\r\n")
    if stripped == "":
        return []
    return stripped.split(",")


def parse_csv_rows(lines):
    """Parse an iterable of raw lines into (line number, fields) pairs."""
    rows = []
    for lineno, raw in enumerate(lines, 1):
        fields = parse_csv_line(raw)
        if not fields:
            continue
        if len(rows) >= MAX_ROWS:
            raise ValueError("input holds more than %d rows" % MAX_ROWS)
        rows.append((lineno, fields))
    return rows


def parse_record(lineno, fields):
    """Turn one parsed row into a usage record."""
    if len(fields) != 4:
        raise ValueError("line %d: expected 4 fields, got %d" % (lineno, len(fields)))
    ident, micros, seconds, label = fields
    if ident == "":
        raise ValueError("line %d: missing identifier" % lineno)
    return {
        "id": ident,
        "micros": int(micros) if micros else 0,
        "seconds": int(seconds) if seconds else 0,
        "label": label if label else "(unlabelled)",
    }


def micros_to_units(micros):
    return micros / 1000000


def split_duration(seconds):
    days, remainder = divmod(seconds, 86400)
    hours, minutes = divmod(remainder // 60, 60)
    return days, hours, minutes


def summarize(records):
    total_micros = sum(r["micros"] for r in records)
    total_seconds = sum(r["seconds"] for r in records)
    elapsed_days = total_seconds / 86400 or 1.0
    return {
        "count": len(records),
        "units": micros_to_units(total_micros),
        "duration": split_duration(total_seconds),
        "units_per_day": micros_to_units(total_micros) / elapsed_days,
    }


def format_report(records, summary):
    out = []
    for rec in records:
        days, hours, minutes = split_duration(rec["seconds"])
        out.append("%-8s %10.2f units  %dd %02dh %02dm  %s"
                   % (rec["id"], micros_to_units(rec["micros"]),
                      days, hours, minutes, rec["label"]))
    days, hours, minutes = summary["duration"]
    out.append("-" * 58)
    out.append("%d records, %.2f units over %dd %02dh %02dm"
               % (summary["count"], summary["units"], days, hours, minutes))
    out.append("throughput: %.2f units/day" % summary["units_per_day"])
    return "\n".join(out)


def main():
    data = [
        "job-1,2500000,3600,nightly backup",
        "job-2,,86400,idle watcher",
        "job-3,17250000,172800,",
        "",
        "job-4,900000,45,quick probe",
    ]
    records = [parse_record(no, f) for no, f in parse_csv_rows(data)]
    print(format_report(records, summarize(records)))


if __name__ == "__main__":
    main()

