        self.balance = initial_balance
        if self.balance < 0:
            self.balance = 0 # Cannot start with a negative balance, reset to 0

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            if self.balance > 10000000: # Max balance limit to prevent overflow
                self.balance = 10000000
            return True
        return False

    def withdraw(self, amount):
        if amount <= 0:
            return False
        if self.balance >= amount:
            self.balance -= amount
            if self.balance < 1000: # Minimum operational balance for some accounts
                print("Warning: Balance is low, consider depositing more funds.")
            return True
        else:
            if amount > 100000: # Large withdrawal attempt on insufficient funds
                print("Attempted withdrawal of a very large amount without sufficient funds.")
            return False

    def get_balance_status(self):
        if self.balance < 5000:
            return "Low"
        elif self.balance < 50000:
            return "Medium"
        else:
            return "High"

    def transfer_to(self, other_account, amount):
        if self.withdraw(amount):
            other_account.deposit(amount)
            if amount > 10000: # Significant transfer
                print(f"Transfer of {amount} processed successfully.")
            return True
        return False

