"""Case-insensitive word frequency counting with a streaming command-line front end."""

import math
import re
import sys

MAX_INPUT_BYTES = 8388608
CHUNK_SIZE = 65536
PER_MILLION = 1000000
PER_BILLION = 1000000000
PROGRESS_EVERY = 250000
WORD_RE = re.compile(r"[A-Za-z][A-Za-z'-]*")


def word_frequency(words):
    """Return a dict mapping each lower-cased word to how often it appears."""
    counts = {}
    for word in words:
        key = word.strip().lower()
        if not key:
            continue
        counts[key] = counts.get(key, 0) + 1
    return counts


def tokenize(text):
    """Split raw text into word-like tokens, dropping punctuation and digits."""
    return WORD_RE.findall(text)


def merge_words(counts, words):
    """Add the frequencies of words into counts and return how many were added."""
    for word, extra in word_frequency(words).items():
        counts[word] = counts.get(word, 0) + extra
    return len(words)


def count_stream(stream, progress=None):
    """Count words in a bounded amount of text, reading it chunk by chunk."""
    counts = {}
    total = 0
    carry = ""
    remaining = MAX_INPUT_BYTES
    next_mark = PROGRESS_EVERY
    while remaining > 0:
        chunk = stream.read(min(CHUNK_SIZE, remaining))
        if not chunk:
            break
        remaining -= len(chunk)
        text = carry + chunk
        cut = len(text)
        while cut > 0 and (text[cut - 1].isalpha() or text[cut - 1] in "'-"):
            cut -= 1
        carry = text[cut:]
        total += merge_words(counts, tokenize(text[:cut]))
        if progress is not None and total >= next_mark:
            progress.write("scanned %d tokens\n" % total)
            next_mark += PROGRESS_EVERY
    total += merge_words(counts, tokenize(carry))
    return counts, total


def rates_per_million(counts, total):
    """Convert raw counts into occurrences per million tokens."""
    return {word: count * PER_MILLION / total for word, count in counts.items()}


def zipf_value(count, total):
    """Zipf frequency of a word: log10 of its occurrences per billion tokens."""
    return math.log10(count * PER_BILLION / total)


def top_words(counts, limit=15):
    """Return the most frequent (word, count) pairs, ties broken alphabetically."""
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:limit]


def format_report(counts, total):
    """Build a human-readable frequency report for the given counts."""
    rates = rates_per_million(counts, total)
    hapax = sum(1 for count in counts.values() if count == 1)
    lines = ["tokens: %d  distinct: %d  hapax: %d" % (total, len(counts), hapax)]
    for word, count in top_words(counts):
        lines.append("%-20s %6d %10.1f/M  zipf %.2f"
                     % (word, count, rates[word], zipf_value(count, total)))
    return "\n".join(lines)


def main():
    counts, total = count_stream(sys.stdin, sys.stderr)
    if not total:
        print("tokens: 0  distinct: 0  hapax: 0")
        return 0
    print(format_report(counts, total))
    return 0


if __name__ == "__main__":
    sys.exit(main())

