            flags[i * i::i] = bytearray(len(range(i * i, limit + 1, i)))
    return [i for i, is_prime in enumerate(flags) if is_prime]


_SMALL_PRIMES = _sieve(SIEVE_LIMIT)


def prime_factors(n):
    """Return the multiset of prime factors of ``n`` in ascending order."""
    if n < 2:
        raise ValueError("n must be at least 2 to have prime factors")
    if n > MAX_SUPPORTED:
        raise ValueError("n is too large for trial division")
    if n in _CACHE:
        return list(_CACHE[n])
    factors = []
    remaining = n
    for p in _SMALL_PRIMES:
        if p * p > remaining:
            break
        while remaining % p == 0:
            factors.append(p)
            remaining //= p
    candidate = SIEVE_LIMIT + 1
    while candidate * candidate <= remaining:
        while remaining % candidate == 0:
            factors.append(candidate)
            remaining //= candidate
        candidate += 2
    if remaining > 1:
        factors.append(remaining)
    if n < 65_536:
        _CACHE[n] = list(factors)
    return factors


def factor_counts(n):
    """Return ``(prime, exponent)`` pairs for ``n`` in ascending order."""
    counts = {}
    for p in prime_factors(n):
        counts[p] = counts.get(p, 0) + 1
    return sorted(counts.items())


def divisors(n):
    """Return every positive divisor of ``n`` in ascending order."""
    result = [1]
    for prime, exponent in factor_counts(n):
        powers = [prime ** e for e in range(1, exponent + 1)]
        result += [d * p for d in result for p in powers]
    return sorted(result)


def format_factorization(n):
    """Render ``n`` as a product of prime powers."""
    parts = []
    for prime, exponent in factor_counts(n):
        parts.append(str(prime) if exponent == 1 else "{}^{}".format(prime, exponent))
    return "{} = {}".format(n, " * ".join(parts))


def main():
    target = int(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_TARGET
    print(format_factorization(target))
    print("factors : {}".format(prime_factors(target)))
    minute_slots = [d for d in divisors(SECONDS_PER_DAY) if d >= 60]
    print("day divisors of a minute or more: {}".format(len(minute_slots)))


if __name__ == "__main__":
    main()

