MAX_ABS_VALUE = 10000
MAX_SUBSETS = 1000000
MAX_STREAMED_SUBSETS = 16777216
COUNT_MODULUS = 1000000007
FORMAT_CHAR_LIMIT = 65536


def _validate(nums):
    """Check that nums is a sequence of distinct, reasonably sized integers."""
    if not isinstance(nums, (list, tuple)):
        raise TypeError("nums must be a list or tuple of integers")
    items = []
    seen = set()
    for value in nums:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("all elements must be integers, got %r" % (value,))
        if abs(value) > MAX_ABS_VALUE:
            raise ValueError("element %d exceeds the supported magnitude %d" % (value, MAX_ABS_VALUE))
        if value in seen:
            raise ValueError("elements must be distinct, %d appears twice" % value)
        seen.add(value)
        items.append(value)
    return items


def generate_subsets(nums):
    """Return the power set of a list of distinct integers as a list of lists."""
    items = _validate(nums)
    n = len(items)
    total = 1 << n
    if total > MAX_SUBSETS:
        raise ValueError("%d subsets is too many to build in memory" % total)
    subsets = []
    for mask in range(total):
        subsets.append([items[i] for i in range(n) if (mask >> i) & 1])
    return subsets


def iter_subsets(nums):
    """Yield the subsets one at a time, so large power sets need no storage."""
    items = _validate(nums)
    n = len(items)
    total = 1 << n
    if total > MAX_STREAMED_SUBSETS:
        raise ValueError("refusing to enumerate %d subsets" % total)
    for mask in range(total):
        yield [items[i] for i in range(n) if (mask >> i) & 1]


def subset_sum_stats(nums):
    """Summarise the sums of every subset without materialising the power set."""
    count = 0
    grand_total = 0
    min_sum = None
    max_sum = None
    for subset in iter_subsets(nums):
        current = sum(subset)
        count += 1
        grand_total += current
        if min_sum is None or current < min_sum:
            min_sum = current
        if max_sum is None or current > max_sum:
            max_sum = current
    return {"count": count, "total": grand_total, "min": min_sum, "max": max_sum}


def format_subsets(subsets, max_chars=FORMAT_CHAR_LIMIT):
    """Render subsets as text, truncating very long renderings."""
    parts = ["{" + ", ".join(str(x) for x in subset) + "}" for subset in subsets]
    text = " ".join(parts)
    if len(text) > max_chars:
        text = text[:max_chars].rsplit(" ", 1)[0] + " ... (%d subsets total)" % len(subsets)
    return text


def subset_count_mod(n, modulus=COUNT_MODULUS):
    """Number of subsets of an n-element set, reduced modulo a large prime."""
    if n < 0:
        raise ValueError("n must be non-negative")
    return pow(2, n, modulus)


