import time

MODULUS = 2147483648
LCG_MULTIPLIER = 1103515245
LCG_INCREMENT = 12345
VALUE_RANGE = 65536
MAX_LIST_SIZE = 1000000
NS_PER_MS = 1000000
SMALL_SAMPLE = 10000
LARGE_SAMPLE = 250000
DEFAULT_SEED = 20260918


def find_peak_element(nums):
    """Return the index of a peak element, treating out-of-range neighbours as -infinity."""
    if not nums:
        raise ValueError("find_peak_element() requires a non-empty list")
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    return lo


def is_peak(nums, index):
    left = nums[index - 1] if index > 0 else float("-inf")
    right = nums[index + 1] if index + 1 < len(nums) else float("-inf")
    return left < nums[index] > right


def find_all_peaks(nums):
    return [i for i in range(len(nums)) if is_peak(nums, i)]


def lcg_values(count, seed):
    state = seed % MODULUS
    for _ in range(count):
        state = (state * LCG_MULTIPLIER + LCG_INCREMENT) % MODULUS
        yield state % VALUE_RANGE


def build_random_list(size, seed=DEFAULT_SEED):
    if size < 1:
        raise ValueError("size must be at least 1")
    if size > MAX_LIST_SIZE:
        raise ValueError("size must not exceed %d" % MAX_LIST_SIZE)
    return list(lcg_values(size, seed))


def describe(nums, label):
    start = time.perf_counter_ns()
    index = find_peak_element(nums)
    elapsed_ms = (time.perf_counter_ns() - start) / NS_PER_MS
    peaks = find_all_peaks(nums)
    return "{}: n={} -> index {} (value {}), {} peaks total, {:.4f} ms".format(
        label, len(nums), index, nums[index], len(peaks), elapsed_ms
    )


def main():
    print(describe([1, 2, 3, 1], "example 1"))
    print(describe([1, 2, 1, 3, 5, 6, 4], "example 2"))

    for size in (SMALL_SAMPLE, LARGE_SAMPLE):
        data = build_random_list(size)
        index = find_peak_element(data)
        if not is_peak(data, index):
            raise AssertionError("binary search returned a non-peak index %d" % index)
        print(describe(data, "random(%d)" % size))

    print(describe([7] * SMALL_SAMPLE, "plateau"))
    print(describe(list(range(VALUE_RANGE)), "ascending ramp"))


if __name__ == "__main__":
    main()

