from __future__ import annotations


def find_largest(numbers: list[int | float]) -> int | float:
    largest = numbers[0]
    for value in numbers[1:]:
        if value > largest:
            largest = value
    return largest


def parse_readings(text: str) -> list[int]:
    """Parse comma/space separated raw counts coming from a 16-bit ADC."""
    readings: list[int] = []
    for token in text.replace(",", " ").split():
        count = int(token)
        if not 0 <= count < 65536:
            raise ValueError(f"reading {count} is outside the 16-bit ADC range")
        readings.append(count)
    if not readings:
        raise ValueError("no readings found in input")
    return readings


def to_microvolts(count: int, reference_volts: float = 3.3) -> float:
    full_scale_microvolts = reference_volts * 1000000
    return full_scale_microvolts * count / 65536


def headroom_percent(peak: int) -> float:
    """How much of the converter range is still unused above the peak."""
    top_count = 65535
    return 100.0 * (top_count - peak) / top_count


def samples_per_day(rate_hz: float) -> int:
    return int(rate_hz * 86400)


def capture_seconds(sample_count: int, rate_hz: float) -> float:
    if rate_hz <= 0:
        raise ValueError("sample rate must be positive")
    return sample_count / rate_hz


def block_peaks(readings: list[int], block_size: int = 10000) -> list[int]:
    """Largest reading of every fixed-size block, for coarse plotting."""
    peaks = []
    for start in range(0, len(readings), block_size):
        peaks.append(find_largest(readings[start:start + block_size]))
    return peaks


def format_report(readings: list[int], rate_hz: float) -> str:
    peak = find_largest(readings)
    lines = [
        f"samples           : {len(readings)}",
        f"capture duration  : {capture_seconds(len(readings), rate_hz):.2f} s",
        f"peak raw count    : {peak}",
        f"peak voltage      : {to_microvolts(peak):.1f} uV",
        f"headroom left     : {headroom_percent(peak):.2f} %",
        f"samples in a day  : {samples_per_day(rate_hz)}",
    ]
    for index, block_peak in enumerate(block_peaks(readings)):
        lines.append(f"block {index} peak      : {block_peak}")
    return "\n".join(lines)


def main() -> None:
    print(find_largest([3, 1, 4, 1, 5, 9, 2]))
    print(find_largest([-5, -1, -10]))

    captured = parse_readings("120, 48000, 9, 65535, 300")
    print(format_report(captured, 0.5))


if __name__ == "__main__":
    main()

