"""Common positive divisors of two integers, plus a few practical helpers."""

SECONDS_PER_DAY = 86400
MICROS_PER_SECOND = 1000000
MAX_BLOCK_FRAMES = 10000
CD_SAMPLE_RATE = 44100
DAT_SAMPLE_RATE = 48000
MAX_SHOWN_DIVISORS = 12


def _positive(n: int) -> int:
    """Return n if it is a positive integer, otherwise raise ValueError."""
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError(f"expected a positive integer, got {n!r}")
    return n


def _gcd(a: int, b: int) -> int:
    """Euclidean greatest common divisor of two positive integers."""
    while b:
        a, b = b, a % b
    return a


def divisors_of(n: int) -> list[int]:
    """All positive divisors of n, in increasing order."""
    n = _positive(n)
    small, large = [], []
    i = 1
    while i * i <= n:
        if n % i == 0:
            small.append(i)
            if i != n // i:
                large.append(n // i)
        i += 1
    return small + large[::-1]


def common_divisors(n1: int, n2: int) -> list[int]:
    """Every positive integer that divides both n1 and n2."""
    return divisors_of(_gcd(_positive(n1), _positive(n2)))


def greatest_common_divisor_under(n1: int, n2: int, limit: int) -> int | None:
    """Largest common divisor of n1 and n2 that does not exceed limit."""
    usable = [d for d in common_divisors(n1, n2) if d <= limit]
    return usable[-1] if usable else None


def common_periods_seconds(days_a: int, days_b: int) -> list[int]:
    """Durations (in seconds) that tile both a days_a and a days_b span."""
    return [d * SECONDS_PER_DAY for d in common_divisors(days_a, days_b)]


def common_intervals_micros(seconds_a: int, seconds_b: int) -> list[int]:
    """Sub-intervals (in microseconds) that evenly split both second counts."""
    return [d * MICROS_PER_SECOND for d in common_divisors(seconds_a, seconds_b)]


def format_report(n1: int, n2: int) -> str:
    """One-line summary of the common divisors of n1 and n2."""
    divs = common_divisors(n1, n2)
    shown = ", ".join(str(d) for d in divs[:MAX_SHOWN_DIVISORS])
    if len(divs) > MAX_SHOWN_DIVISORS:
        shown += ", ..."
    return f"{n1} & {n2}: gcd={divs[-1]} count={len(divs)} -> [{shown}]"


def main() -> None:
    pairs = [(12, 18), (7, 13), (CD_SAMPLE_RATE, DAT_SAMPLE_RATE),
             (MICROS_PER_SECOND, SECONDS_PER_DAY)]
    for a, b in pairs:
        print(format_report(a, b))

    block = greatest_common_divisor_under(CD_SAMPLE_RATE, DAT_SAMPLE_RATE, MAX_BLOCK_FRAMES)
    print(f"best shared audio block size below {MAX_BLOCK_FRAMES} frames: {block}")
    print(f"periods shared by 30-day and 45-day spans: {common_periods_seconds(30, 45)} s")
    print(f"shared sub-intervals of 60s and 90s: {common_intervals_micros(60, 90)} us")


if __name__ == "__main__":
    main()

