"""Utilities built around the decimal digit sum of a non-negative integer."""


def _build_digit_sums() -> bytearray:
    """Digit sums of every value that fits in four decimal digits."""
    table = bytearray(10000)
    for k in range(10000):
        table[k] = table[k // 10] + k % 10
    return table


_DIGIT_SUMS = _build_digit_sums()


def sum_digits(n: int) -> int:
    """Return the sum of the decimal digits of a non-negative integer."""
    if n < 0:
        raise ValueError("sum_digits requires a non-negative integer")
    total = 0
    while n >= 10000:
        n, chunk = divmod(n, 10000)
        total += _DIGIT_SUMS[chunk]
    return total + _DIGIT_SUMS[n]


def digital_root(n: int) -> int:
    """Repeatedly sum the digits until a single digit remains."""
    while n > 9:
        n = sum_digits(n)
    return n


def additive_persistence(n: int) -> int:
    """Number of digit-sum steps needed to reach a single digit."""
    steps = 0
    while n > 9:
        n = sum_digits(n)
        steps += 1
    return steps


def is_harshad(n: int) -> bool:
    """A Harshad number is divisible by the sum of its own digits."""
    if n == 0:
        return False
    return n % sum_digits(n) == 0


def digit_sum_total(limit: int = 1000000) -> int:
    """Sum of sum_digits(k) for every k in [0, limit)."""
    return sum(sum_digits(k) for k in range(limit))


def describe(n: int) -> str:
    """One-line report about the digit sum of n and its derived values."""
    return (
        f"{n:>10}  digit sum={sum_digits(n):>3}  root={digital_root(n)}  "
        f"persistence={additive_persistence(n)}  "
        f"harshad={'yes' if is_harshad(n) else 'no'}"
    )


def main() -> None:
    samples = (
        12345,
        7,
        86400,
        65536,
        999999999,
    )
    for value in samples:
        print(describe(value))
    print("digit sums of 0..999999 total:", digit_sum_total())
    harshads = [k for k in range(1, 200) if is_harshad(k)]
    print("Harshad numbers under 200:", harshads)


if __name__ == "__main__":
    main()

