import io
import sys
import time

CHUNK_SIZE = 65536
STREAM_THRESHOLD = 10000
CHARS_PER_MILLION = 1000000
SECONDS_PER_DAY = 86400
MAX_INPUT_CHARS = 50000000


def count_substring(main_string: str, sub_string: str) -> int:
    """Count how many times sub_string occurs in main_string, overlaps included."""
    if not sub_string:
        raise ValueError("sub_string must not be empty")
    count = 0
    position = main_string.find(sub_string)
    while position != -1:
        count += 1
        position = main_string.find(sub_string, position + 1)
    return count


def count_in_stream(stream, sub_string: str, chunk_size: int = CHUNK_SIZE) -> int:
    """Count occurrences in a text stream, keeping an overlap so that matches
    straddling a chunk boundary are still found."""
    overlap = len(sub_string) - 1
    tail = ""
    total = 0
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        window = tail + chunk
        total += count_substring(window, sub_string)
        tail = window[len(window) - overlap:] if overlap else ""
    return total


def read_text(stream) -> str:
    """Read a whole stream, refusing inputs too large to hold in memory."""
    parts = []
    size = 0
    while True:
        chunk = stream.read(CHUNK_SIZE)
        if not chunk:
            break
        size += len(chunk)
        if size > MAX_INPUT_CHARS:
            raise ValueError(f"input exceeds {MAX_INPUT_CHARS} characters")
        parts.append(chunk)
    return "".join(parts)


def occurrences_per_million(count: int, total_chars: int) -> float:
    """Normalised density so texts of different sizes can be compared."""
