import sys

MAX_LIST_SPAN = 1000000
MAX_STREAM_SPAN = 100000000
CHUNK_SIZE = 65536
MAX_LISTED = 10000
DEFAULT_END = 86400


def first_even(start: int) -> int:
    """Smallest even integer greater than or equal to start."""
    return start if start % 2 == 0 else start + 1


def generate_even_numbers(start: int, end: int) -> list[int]:
    """Return every even integer in [start, end], ascending."""
    if end < start:
        return []
    if end - start > MAX_LIST_SPAN:
        raise ValueError(
            "span %d is too wide to materialise; limit is %d"
            % (end - start, MAX_LIST_SPAN)
        )
    return list(range(first_even(start), end + 1, 2))


def count_even_numbers(start: int, end: int) -> int:
    """Count the evens in [start, end] without building the list."""
    first = first_even(start)
    if first > end:
        return 0
    return (end - first) // 2 + 1


def sum_even_numbers(start: int, end: int) -> int:
    """Sum the evens in [start, end] with the arithmetic series formula."""
    n = count_even_numbers(start, end)
    if n == 0:
        return 0
    first = first_even(start)
    return n * (2 * first + 2 * (n - 1)) // 2


def iter_even_chunks(start: int, end: int, chunk: int = CHUNK_SIZE):
    """Yield the evens of [start, end] in blocks of at most chunk items."""
    value = first_even(start)
    while value <= end:
        block = list(range(value, min(value + 2 * chunk, end + 1), 2))
        yield block
        value = block[-1] + 2


def write_even_numbers(start: int, end: int, out) -> int:
    """Write one even number per line, streaming to keep memory flat."""
    if end - start > MAX_STREAM_SPAN:
        raise ValueError("span %d exceeds the streaming limit" % (end - start))
    written = 0
    for block in iter_even_chunks(start, end):
        out.write("\n".join(str(v) for v in block) + "\n")
        written += len(block)
    return written


def preview_evens(start: int, end: int, limit: int = 5) -> str:
    """Render the evens of a range, eliding the middle of long results."""
    count = count_even_numbers(start, end)
    if count <= 2 * limit:
        return "[" + ", ".join(str(v) for v in generate_even_numbers(start, end)) + "]"
    first = first_even(start)
    last = first + 2 * (count - 1)
    head = ", ".join(str(first + 2 * i) for i in range(limit))
    tail = ", ".join(str(last - 2 * i) for i in reversed(range(limit)))
    return "[%s, ..., %s]" % (head, tail)


def format_report(start: int, end: int) -> str:
    """One summary line describing the evens of a single range."""
    count = count_even_numbers(start, end)
    limit = count if count <= MAX_LISTED else 5
    return "%-18s count=%-9d sum=%-14d %s" % (
        "[%d, %d]" % (start, end),
        count,
        sum_even_numbers(start, end),
        preview_evens(start, end, limit),
    )


def main(argv: list[str]) -> None:
    args = list(argv[1:])
    stream = bool(args) and args[0] == "--list"
    if stream:
        args.pop(0)
    if len(args) == 2:
        start, end = int(args[0]), int(args[1])
    elif args:
        raise SystemExit("usage: evens.py [--list] [start end]")
    else:
        start, end = 0, DEFAULT_END
    print(format_report(start, end))
    if stream:
        write_even_numbers(start, end, sys.stdout)


if __name__ == "__main__":
    main(sys.argv)

