MODULUS = 1000000007


def power_recursive(base: float, exponent: int) -> float:
    """Return base ** exponent for a non-negative integer exponent."""
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    if exponent == 0:
        return 1.0
    half = power_recursive(base, exponent // 2)
    if exponent % 2:
        return half * half * base
    return half * half


def power_mod(base: int, exponent: int, modulus: int = MODULUS) -> int:
    """Return (base ** exponent) % modulus without building huge integers."""
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    if modulus <= 0:
        raise ValueError("modulus must be positive")
    if exponent == 0:
        return 1 % modulus
    half = power_mod(base, exponent // 2, modulus)
    squared = half * half % modulus
    if exponent % 2:
        return squared * base % modulus
    return squared


def rate_from_basis_points(basis_points: float) -> float:
    """One basis point is one hundredth of a percent."""
    return basis_points / 10000


def compound_factor(basis_points: float, periods: int) -> float:
    return power_recursive(1.0 + rate_from_basis_points(basis_points), periods)


def growth_over_days(basis_points_per_second: float, days: int) -> float:
    seconds = days * 86400
    return compound_factor(basis_points_per_second, seconds)


def to_fixed_point(value: float) -> int:
    """Encode a float as Q16.16 fixed point."""
    return round(value * 65536)


def from_fixed_point(raw: int) -> float:
    return raw / 65536


def format_cents(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}${cents // 100}.{cents % 100:02d}"


def main() -> None:
    print(power_recursive(2, 3))
    print(power_recursive(5, 0))
    for exponent in (0, 1, 8, 16):
        print(f"2^{exponent} = {power_recursive(2.0, exponent)}")
    print(f"7^1000000 mod {MODULUS} = {power_mod(7, 1000000)}")

    principal = 250000
    grown = round(principal * compound_factor(175, 12))
    print(f"{format_cents(principal)} at 175bp for 12 periods -> {format_cents(grown)}")
    print(f"1bp per second for 30 days multiplies capital by {growth_over_days(1, 30):.4f}")

    raw = to_fixed_point(power_recursive(1.5, 4))
    print(f"1.5^4 as Q16.16 raw={raw}, decoded={from_fixed_point(raw)}")


if __name__ == "__main__":
    main()

