import os
import time

FACES = 6
ENTROPY_MODULUS = 65536
DEFAULT_TRIALS = 10000
MAX_TRIALS = 1000000
SECONDS_PER_DAY = 86400
MICROSECONDS_PER_SECOND = 1000000
CHI_SQUARE_5PCT_5DF = 11.07


def roll_die() -> int:
    """Return a uniformly distributed integer in 1..6."""
    limit = ENTROPY_MODULUS - ENTROPY_MODULUS % FACES
    while True:
        draw = int.from_bytes(os.urandom(2), "big")
        if draw < limit:
            return draw % FACES + 1


def roll_many(count: int = DEFAULT_TRIALS) -> list:
    """Roll the die `count` times and return the results in order."""
    if not isinstance(count, int):
        raise TypeError("count must be an integer")
    if count < 1 or count > MAX_TRIALS:
        raise ValueError("count must be between 1 and %d" % MAX_TRIALS)
    return [roll_die() for _ in range(count)]


def tally(rolls: list) -> dict:
    counts = {face: 0 for face in range(1, FACES + 1)}
    for value in rolls:
        counts[value] += 1
    return counts


def chi_square(counts: dict) -> float:
    total = sum(counts.values())
    expected = total / FACES
    return sum((seen - expected) ** 2 / expected for seen in counts.values())


def longest_run(rolls: list) -> int:
    longest = current = 1
    for previous, value in zip(rolls, rolls[1:]):
        current = current + 1 if value == previous else 1
        longest = max(longest, current)
    return longest


def format_report(counts: dict, elapsed: float) -> str:
    total = sum(counts.values())
    lines = ["Rolls: %d" % total]
    for face in sorted(counts):
        share = 100.0 * counts[face] / total
        lines.append("  %d: %6d  %5.2f%%  %s" % (face, counts[face], share, "#" * int(share)))
    mean = sum(face * n for face, n in counts.items()) / total
    lines.append("Mean pip value: %.4f (fair die: 3.5000)" % mean)
    stat = chi_square(counts)
    lines.append("Chi-square: %.3f (5%% critical value %.2f)" % (stat, CHI_SQUARE_5PCT_5DF))
    lines.append("Verdict: %s" % ("consistent with fair" if stat <= CHI_SQUARE_5PCT_5DF else "suspicious"))
    if elapsed > 0:
        per_second = total / elapsed
        lines.append("Throughput: %.0f rolls/s, %.0f rolls/day" % (per_second, per_second * SECONDS_PER_DAY))
        lines.append("Latency: %.2f us/roll" % (elapsed * MICROSECONDS_PER_SECOND / total))
    return "\n".join(lines)


def main() -> None:
    print("Three sample rolls: %d, %d, %d" % (roll_die(), roll_die(), roll_die()))
    start = time.perf_counter()
    rolls = roll_many()
    elapsed = time.perf_counter() - start
    print(format_report(tally(rolls), elapsed))
    print("Longest run of identical faces: %d" % longest_run(rolls))


if __name__ == "__main__":
    main()

