import sys


def count_uppercase(text: str) -> int:
    """Count the uppercase letters in the given string."""
    return sum(1 for ch in text if ch.isupper())


def count_uppercase_in_chunks(stream, chunk_size: int = 65536, progress=None):
    """Count uppercase letters in a text stream, returning (count, length)."""
    count = 0
    length = 0
    next_progress = 1000000
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        length += len(chunk)
        count += count_uppercase(chunk)
        if progress is not None and length >= next_progress:
            progress(count, length)
            next_progress = length + 1000000
    return count, length


def uppercase_rate(count: int, length: int) -> int:
    """Uppercase letters per 10000 characters, rounded down."""
    if length == 0:
        return 0
    return count * 10000 // length


def is_shouting(count: int, length: int) -> bool:
    """True when more than half of the characters are uppercase."""
    return uppercase_rate(count, length) > 5000


def format_report(label: str, count: int, length: int) -> str:
    rate = uppercase_rate(count, length)
    tone = "shouting" if is_shouting(count, length) else "normal"
    return "{0}: {1} uppercase in {2} chars ({3} per 10000, {4})".format(
        label, count, length, rate, tone
    )


def main(argv) -> int:
    paths = argv[1:] or ["-"]
    total_count = 0
    total_length = 0
    status = 0

    def progress(count, length):
        print("  ... {0} uppercase so far in {1} chars".format(count, length),
              file=sys.stderr)

    for path in paths:
        if path == "-":
            count, length = count_uppercase_in_chunks(sys.stdin, progress=progress)
        else:
            try:
                with open(path, encoding="utf-8", errors="replace") as handle:
                    count, length = count_uppercase_in_chunks(handle, progress=progress)
            except OSError as exc:
                print("cannot read {0}: {1}".format(path, exc), file=sys.stderr)
                status = 1
                continue
        total_count += count
        total_length += length
        print(format_report(path, count, length))
    if len(paths) > 1:
        print(format_report("total", total_count, total_length))
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv))

