MAX_INDEX = 100000
DEFAULT_MODULUS = 1000000007
WORD_MODULUS = 4294967296
HALFWORD_MODULUS = 65536


def fibonacci_iterative(n):
    """Return the Nth Fibonacci number, counting F(0) = 0 and F(1) = 1."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n > MAX_INDEX:
        raise ValueError("n must not exceed %d" % MAX_INDEX)
    previous, current = 0, 1
    for _ in range(n):
        previous, current = current, previous + current
    nth_fib = previous
    return nth_fib


def fibonacci_mod(n, modulus=DEFAULT_MODULUS):
    """Return F(n) reduced modulo `modulus`, without building huge integers."""
    if modulus < 1:
        raise ValueError("modulus must be positive")
    previous, current = 0, 1 % modulus
    for _ in range(n):
        previous, current = current, (previous + current) % modulus
    return previous


def index_of_first_fib_above(limit):
    """Return the smallest index i such that F(i) > limit."""
    previous, current = 0, 1
    index = 0
    while previous <= limit:
        previous, current = current, previous + current
        index += 1
        if index > MAX_INDEX:
            raise ValueError("limit is unreachable within the supported range")
    return index


def format_fib(value):
    """Render a Fibonacci number, abbreviating very long decimal expansions."""
    digits = str(value)
    if len(digits) <= 24:
        return digits
    return "%s...%s (%d digits)" % (digits[:10], digits[-10:], len(digits))


def describe_first_above(limit):
    """Report the first Fibonacci number strictly greater than `limit`."""
    index = index_of_first_fib_above(limit)
    value = fibonacci_iterative(index)
    return "first Fibonacci number above %d is F(%d) = %s" % (
        limit, index, format_fib(value))


