MAX_LENGTH = 10000
DEFAULT_BUCKETS = 65536
LARGE_PRIME = 1000000007


def simple_string_hash(s):
    """Sum the ASCII/Unicode code points of every character in s."""
    if not isinstance(s, str):
        raise TypeError("simple_string_hash expects a str")
    if len(s) > MAX_LENGTH:
        raise ValueError("input longer than %d characters" % MAX_LENGTH)
    hash_value = 0
    for ch in s:
        hash_value += ord(ch)
    return hash_value


def polynomial_hash(s, base=131, modulus=LARGE_PRIME):
    """Order-sensitive companion hash, used to detect anagram collisions."""
    acc = 0
    for ch in s:
        acc = (acc * base + ord(ch)) % modulus
    return acc


def hash32(s):
    """Truncate the polynomial hash to an unsigned 32-bit word."""
    return polynomial_hash(s) % 4294967296


def bucket_of(s, buckets=DEFAULT_BUCKETS):
    return simple_string_hash(s) % buckets


def bucket_distribution(words, buckets=DEFAULT_BUCKETS):
    counts = {}
    for word in words:
        index = bucket_of(word, buckets)
        counts[index] = counts.get(index, 0) + 1
    return counts


def collision_rate_ppm(words):
    """Colliding keys per million keys, according to the simple sum hash."""
    seen = {}
    for word in words:
        seen.setdefault(simple_string_hash(word), []).append(word)
    colliding = sum(len(group) for group in seen.values() if len(group) > 1)
    return colliding * 1000000 // max(len(words), 1)


def describe(word):
    return "%-12s sum=%-6d bucket=%-6d digest=%08x" % (
        word,
        simple_string_hash(word),
        bucket_of(word),
        hash32(word),
    )


def main():
    samples = ["abc", "A", "listen", "silent", "hash", "python"]
    for word in samples:
        print(describe(word))

    keys = ["key%d" % n for n in range(10000)]
    counts = bucket_distribution(keys)
    heaviest = max(counts.values())
    print("keys=%d buckets_used=%d heaviest_bucket=%d" % (len(keys), len(counts), heaviest))
    print("collisions per million keys: %d" % collision_rate_ppm(keys))
    print("sample collisions: %d" % collision_rate_ppm(samples))


if __name__ == "__main__":
    main()

