ISBN13_PREFIX = 9780000000000


def _english_registrant_width(body):
    """Width of the registrant element for an 8-digit English-group body."""
    number = int(body)
    if number < 2000000:
        return 2
    if number < 7000000:
        return 3
    if number < 8500000:
        return 4
    if number < 9000000:
        return 5
    if number < 9500000:
        return 6
    return 7


def _french_registrant_width(body):
    """Width of the registrant element for an 8-digit French-group body."""
    number = int(body)
    if number < 2000000:
        return 2
    if number < 3500000:
        return 3
    if number < 4000000:
        return 5
    if number < 7000000:
        return 3
    if number < 8400000:
        return 4
    if number < 9000000:
        return 5
    if number < 9500000:
        return 6
    return 7


WIDTH_BY_GROUP = {
    "0": _english_registrant_width,
    "1": _english_registrant_width,
    "2": _french_registrant_width,
}


def _clean(isbn):
    return isbn.replace("-", "").replace(" ", "").upper()


def _digit_values(cleaned):
    values = []
    for index, char in enumerate(cleaned):
        if char.isdigit():
            values.append(int(char))
        elif char == "X" and index == 9:
            values.append(10)
        else:
            return None
    return values


def is_valid_isbn10(isbn):
    cleaned = _clean(isbn)
    if len(cleaned) != 10:
        return False
    values = _digit_values(cleaned)
    if values is None:
        return False
    weighted = sum(value * (10 - index) for index, value in enumerate(values))
    return weighted % 11 == 0


def hyphenate(isbn):
    cleaned = _clean(isbn)
    if not is_valid_isbn10(cleaned):
        raise ValueError("not a valid ISBN-10: %r" % isbn)
    width_of = WIDTH_BY_GROUP.get(cleaned[0])
    if width_of is None:
        return cleaned
    body = cleaned[1:9]
    width = width_of(body)
    return "-".join([cleaned[0], body[:width], body[width:], cleaned[9]])


def to_isbn13(isbn):
    cleaned = _clean(isbn)
    if not is_valid_isbn10(cleaned):
        raise ValueError("not a valid ISBN-10: %r" % isbn)
    body = str(ISBN13_PREFIX + int(cleaned[:9]) * 10)[:12]
    total = sum(int(d) * (3 if i % 2 else 1) for i, d in enumerate(body))
    return body + str((10 - total % 10) % 10)


def main():
    samples = ["0321765726", "0321765727", "0-19-853453-1", "097522980X",
               "2 266 11156 6", "12345"]
    for sample in samples:
        valid = is_valid_isbn10(sample)
        print("%-15s valid=%s" % (sample, valid))
        if valid:
            print("    %s -> %s" % (hyphenate(sample), to_isbn13(sample)))


if __name__ == "__main__":
    main()

