import time

VOWELS = frozenset("aeiou")
MAX_TEXT_CHARS = 10000
CACHE_LIMIT = 65536

_cache = {}


def _split_letters(word):
    """Return (leading non-letter, letters, trailing non-letter) of a token."""
    start = 0
    while start < len(word) and not word[start].isalpha():
        start += 1
    end = len(word)
    while end > start and not word[end - 1].isalpha():
        end -= 1
    return word[:start], word[start:end], word[end:]


def _cluster_length(letters):
    """Length of the initial consonant cluster ('qu' counts as one unit)."""
    index = 0
    while index < len(letters) and letters[index].lower() not in VOWELS:
        if letters[index].lower() == "q" and letters[index + 1:index + 2].lower() == "u":
            index += 2
            break
        index += 1
    return index


def to_pig_latin(word):
    if not isinstance(word, str):
        raise TypeError("word must be a string")
    if word in _cache:
        return _cache[word]

    prefix, letters, suffix = _split_letters(word)
    if not letters:
        return word

    cluster = _cluster_length(letters)
    if cluster == 0:
        body = letters + "way"
    elif cluster == len(letters):
        body = letters + "ay"
    else:
        body = letters[cluster:] + letters[:cluster] + "ay"

    if letters[0].isupper():
        body = body.capitalize()
    pig_latin_word = prefix + body + suffix

    if len(_cache) >= CACHE_LIMIT:
        _cache.clear()
    _cache[word] = pig_latin_word
    return pig_latin_word


def translate_text(text):
    if len(text) > MAX_TEXT_CHARS:
        raise ValueError("text must not exceed %d characters" % MAX_TEXT_CHARS)
    return " ".join(to_pig_latin(token) for token in text.split())


def performance_report(word_count, elapsed_seconds):
    seconds = max(elapsed_seconds, 1e-9)
    micros_per_word = seconds / word_count * 1000000
    words_per_day = word_count / seconds * 86400
    return (
        "%d words in %.4f s (%.2f us/word, %.1f million words/day)"
        % (word_count, seconds, micros_per_word, words_per_day / 1000000)
    )


def main():
    print(to_pig_latin("apple"))
    print(to_pig_latin("hello"))

    sample = "The quick brown fox jumps over an idle yellow dog, silently."
    print(translate_text(sample))

    repeats = 500
    start = time.perf_counter()
    for _ in range(repeats):
        translate_text(sample)
    elapsed = time.perf_counter() - start
    print(performance_report(len(sample.split()) * repeats, elapsed))


if __name__ == "__main__":
    main()

