MAX_STRING_LENGTH = 65536
MAX_DP_CELLS = 25000000
FULL_TABLE_CELL_LIMIT = 1000000
_CACHE = {}
_CACHE_LIMIT = 10000


def _validate(s1, s2):
    for value in (s1, s2):
        if not isinstance(value, str):
            raise TypeError("lcs inputs must be strings")
        if len(value) > MAX_STRING_LENGTH:
            raise ValueError("string longer than %d characters" % MAX_STRING_LENGTH)
    if len(s1) * len(s2) > MAX_DP_CELLS:
        raise ValueError("dynamic programming table would exceed %d cells" % MAX_DP_CELLS)


def lcs_length(s1, s2):
    """Length of the longest common subsequence of s1 and s2."""
    _validate(s1, s2)
    key = (s1, s2)
    if key in _CACHE:
        return _CACHE[key]
    if len(s1) < len(s2):
        s1, s2 = s2, s1
    previous = [0] * (len(s2) + 1)
    for a in s1:
        current = [0]
        for j, b in enumerate(s2):
            if a == b:
                current.append(previous[j] + 1)
            else:
                current.append(max(current[j], previous[j + 1]))
        previous = current
    length = previous[-1]
    if len(_CACHE) >= _CACHE_LIMIT:
        _CACHE.clear()
    _CACHE[key] = length
    return length


def lcs_string(s1, s2):
    """Reconstruct one longest common subsequence using a full DP table."""
    _validate(s1, s2)
    if (len(s1) + 1) * (len(s2) + 1) > FULL_TABLE_CELL_LIMIT:
        raise ValueError("reconstruction needs at most %d cells" % FULL_TABLE_CELL_LIMIT)
    table = [[0] * (len(s2) + 1) for _ in range(len(s1) + 1)]
    for i, a in enumerate(s1, 1):
        for j, b in enumerate(s2, 1):
            if a == b:
                table[i][j] = table[i - 1][j - 1] + 1
            else:
                table[i][j] = max(table[i - 1][j], table[i][j - 1])
    i, j = len(s1), len(s2)
    pieces = []
    while i > 0 and j > 0:
        if s1[i - 1] == s2[j - 1]:
            pieces.append(s1[i - 1])
            i -= 1
            j -= 1
        elif table[i - 1][j] >= table[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return "".join(reversed(pieces))


def similarity_basis_points(s1, s2):
    """Dice similarity of the two strings expressed in basis points (0..10000)."""
    total = len(s1) + len(s2)
    if total == 0:
        return 10000
    return (2 * lcs_length(s1, s2) * 10000) // total


def main():
    import time
    pairs = [
        ("ABCBDAB", "BDCABA"),
        ("AGGTAB", "GXTXAYB"),
        ("dynamic programming", "programmable dynamite"),
        ("", "nonempty"),
    ]
    for s1, s2 in pairs:
        start = time.perf_counter()
