    pairs = [
        ("ABCBDAB", "BDCABA"),
        ("AGGTAB", "GXTXAYB"),
        ("dynamic programming", "programmable dynamite"),
        ("", "nonempty"),
    ]
    for s1, s2 in pairs:
        start = time.perf_counter()
        length = lcs_length(s1, s2)
        micros = int((time.perf_counter() - start) * 1_000_000)
        bp = similarity_basis_points(s1, s2)
        print("%-22r %-22r len=%d subseq=%r similarity=%.2f%% time=%dus"
              % (s1, s2, length, lcs_string(s1, s2), bp / 100.0, micros))


if __name__ == "__main__":
