    lines = []
    for outcome in OUTCOMES:
        basis_points = 10000 * tally[outcome] // rounds
        lines.append('%-14s %7d  %6.2f%%' % (outcome, tally[outcome], basis_points / 100))
    per_round_us = elapsed / rounds * 1000000
    lines.append('%d rounds in %.4f s (%.2f us per round)' % (rounds, elapsed, per_round_us))
    daily = int(rounds / elapsed * 86400)
    lines.append('projected throughput: %d rounds/day' % daily)
    return '\n'.join(lines)


