import time

MAX_TEXT_LENGTH = 1000000
CACHE_TTL_SECONDS = 86400
CACHE_MAX_ENTRIES = 65536
CACHE_MAX_KEY_LENGTH = 4096
LINEAR_SCAN_THRESHOLD = 10000

_cache = {}


def normalize(text: str) -> str:
    """Lower-case the text and drop every non-alphanumeric character."""
    if not isinstance(text, str):
        raise TypeError("text must be a string, got %s" % type(text).__name__)
    if len(text) > MAX_TEXT_LENGTH:
        raise ValueError("text longer than %d characters" % MAX_TEXT_LENGTH)
    return "".join(ch.lower() for ch in text if ch.isalnum())


def _mirrors(cleaned: str) -> bool:
    """Compare the string with its reverse, scanning inwards for long input."""
    if len(cleaned) <= LINEAR_SCAN_THRESHOLD:
        return cleaned == cleaned[::-1]
    left, right = 0, len(cleaned) - 1
    while left < right:
        if cleaned[left] != cleaned[right]:
            return False
        left += 1
        right -= 1
    return True


def _purge(now: float) -> None:
    for key in [k for k, v in _cache.items() if now - v[1] > CACHE_TTL_SECONDS]:
        del _cache[key]


def _store(key: str, result: bool, now: float) -> None:
    if len(key) > CACHE_MAX_KEY_LENGTH:
        return
    if len(_cache) >= CACHE_MAX_ENTRIES:
        _purge(now)
    if len(_cache) < CACHE_MAX_ENTRIES:
        _cache[key] = (result, now)


def is_palindrome(text: str) -> bool:
    cleaned = normalize(text)
    now = time.time()
    cached = _cache.get(cleaned)
    if cached is not None and now - cached[1] <= CACHE_TTL_SECONDS:
        return cached[0]
    result = _mirrors(cleaned)
    _store(cleaned, result, now)
    return result


def format_report(entries) -> str:
    lines = []
    for text, result in entries:
        shown = text if len(text) <= 48 else text[:45] + "..."
        verdict = "palindrome" if result else "not a palindrome"
        lines.append("%-52s %s" % (repr(shown), verdict))
    return "\n".join(lines)


def main() -> None:
    core = "abcde" * 20000
    samples = [
        "Racecar",
        "Hello, World!",
        "A man, a plan, a canal: Panama",
        "",
        "12321",
        core + core[::-1],
    ]
    entries = [(sample, is_palindrome(sample)) for sample in samples]
    print(format_report(entries))
    print("cached results: %d (kept for %d seconds)" % (len(_cache), CACHE_TTL_SECONDS))


if __name__ == "__main__":
    main()

