import re
import sys
import time
from functools import lru_cache

MAX_PHRASE_CHARS = 10000
ACRONYM_CACHE_SIZE = 65536
NS_PER_MS = 1000000
NS_PER_SECOND = 1000000000
SECONDS_PER_DAY = 86400

WORD_PATTERN = re.compile(r"[A-Za-z]+")

DEFAULT_PHRASES = (
    "For Your Information",
    "  portable network graphics  ",
    "Complementary metal-oxide semiconductor",
    "as-soon-as-possible",
    "GNU Image Manipulation Program",
)


@lru_cache(maxsize=ACRONYM_CACHE_SIZE)
def _initials(phrase: str) -> str:
    return "".join(word[0] for word in WORD_PATTERN.findall(phrase)).upper()


def generate_acronym(phrase: str) -> str:
    if not isinstance(phrase, str):
        raise TypeError("phrase must be a string")
    if len(phrase) > MAX_PHRASE_CHARS:
        raise ValueError(f"phrase exceeds {MAX_PHRASE_CHARS} characters")
    return _initials(phrase)


def acronym_table(phrases):
    return [(phrase.strip(), generate_acronym(phrase)) for phrase in phrases]


def format_report(rows, elapsed_ns: int) -> str:
    if not rows:
        return "no phrases given"
    width = max(len(phrase) for phrase, _ in rows)
    lines = [f"{phrase:<{width}}  ->  {acronym}" for phrase, acronym in rows]
    lines.append(f"{len(rows)} phrases converted in {elapsed_ns / NS_PER_MS:.3f} ms")
    if elapsed_ns:
        rate = len(rows) * NS_PER_SECOND / elapsed_ns
        lines.append(f"throughput: {rate:,.0f} phrases/second")
        lines.append(f"daily capacity: {rate * SECONDS_PER_DAY:,.0f} phrases")
    longest = max(rows, key=lambda row: len(row[1]))
    lines.append(f"longest acronym: {longest[1]} ({len(longest[1])} letters)")
    return "\n".join(lines)


def main(argv):
    phrases = argv[1:] or list(DEFAULT_PHRASES)
    start = time.perf_counter_ns()
    try:
        rows = acronym_table(phrases)
    except (TypeError, ValueError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    elapsed_ns = time.perf_counter_ns() - start
    print(format_report(rows, elapsed_ns))
    info = _initials.cache_info()
    print(f"cache: {info.hits} hits, {info.misses} misses of {info.maxsize} slots")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

