CENT_SCALE = 100
MAX_TRANSACTIONS = 10000
MAX_AMOUNT_CENTS = 100000000
MAX_BALANCE_CENTS = 1000000000
SECONDS_PER_DAY = 86400
SECONDS_PER_YEAR = 31536000


def _to_cents(amount: float) -> int:
    """Convert a currency amount to whole cents to avoid float drift."""
    return int(round(float(amount) * CENT_SCALE))


def validate_transactions(transactions: list) -> None:
    """Reject ledgers that are too long or contain implausible amounts."""
    if len(transactions) > MAX_TRANSACTIONS:
        raise ValueError("ledger exceeds %d transactions" % MAX_TRANSACTIONS)
    for index, amount in enumerate(transactions):
        if not isinstance(amount, (int, float)) or isinstance(amount, bool):
            raise TypeError("transaction %d is not a number: %r" % (index, amount))
        if abs(_to_cents(amount)) > MAX_AMOUNT_CENTS:
            raise ValueError("transaction %d exceeds the single-item limit" % index)


def calculate_final_balance(initial_balance: float, transactions: list) -> float:
    """Return the balance after applying every transaction in order."""
    validate_transactions(transactions)
    total_cents = _to_cents(initial_balance)
    for amount in transactions:
        total_cents += _to_cents(amount)
    if abs(total_cents) > MAX_BALANCE_CENTS:
        raise ValueError("resulting balance is outside the supported range")
    return total_cents / float(CENT_SCALE)


def summarize(initial_balance: float, transactions: list) -> dict:
    """Build a small report describing the movements on the account."""
    deposits = [float(a) for a in transactions if a > 0]
    withdrawals = [float(a) for a in transactions if a < 0]
    return {
        "opening": float(initial_balance),
        "deposit_count": len(deposits),
        "deposit_total": calculate_final_balance(0.0, deposits),
        "withdrawal_count": len(withdrawals),
        "withdrawal_total": calculate_final_balance(0.0, withdrawals),
        "closing": calculate_final_balance(initial_balance, transactions),
    }


def project_interest(balance: float, seconds: int, annual_rate: float) -> float:
    """Simple interest earned on a balance held for a number of seconds."""
    earned = balance * annual_rate * seconds / float(SECONDS_PER_YEAR)
    return _to_cents(earned) / float(CENT_SCALE)


def format_statement(summary: dict) -> str:
    lines = ["Opening balance: %10.2f" % summary["opening"]]
    lines.append("Deposits   (%3d): %10.2f" % (summary["deposit_count"], summary["deposit_total"]))
    lines.append("Withdrawals(%3d): %10.2f" % (summary["withdrawal_count"], summary["withdrawal_total"]))
    lines.append("Closing balance: %10.2f" % summary["closing"])
    if summary["closing"] < 0:
        lines.append("WARNING: account is overdrawn")
    return "\n".join(lines)


def main() -> None:
    print(calculate_final_balance(100.0, [50.0, -20.0, 10.0]))
    print(calculate_final_balance(0.0, [-10.0, -5.0]))

    payroll = [2500.0, -899.95, -42.5, 12500.0, -750.0, -18.75]
    report = summarize(1250.25, payroll)
    print(format_statement(report))

    holding_period = 90 * SECONDS_PER_DAY
    interest = project_interest(report["closing"], holding_period, 0.0215)
    print("Interest over %d seconds: %.2f" % (holding_period, interest))
    print("Projected balance: %.2f" % calculate_final_balance(report["closing"], [interest]))


if __name__ == "__main__":
    main()

